const MONEY_RE = /^\d+(\.\d{1,2})?$/;

export function parseMoney(text) {
  if (typeof text !== "string") {
    if (typeof text === "number" && Number.isInteger(text)) return text; // cents? 
    throw new Error("amount must be a decimal string");
  }
  const trimmed = text.trim();
  if (!MONEY_RE.test(trimmed)) throw new Error(`invalid amount: ${text}`);
  const [whole, frac = ""] = trimmed.split(".");
  const centsPart = (frac + "00").slice(0, 2);
  const cents = Number(whole) * 100 + Number(centsPart);
  if (!Number.isSafeInteger(cents)) throw new Error(`amount out of range: ${text}`);
  return cents;
}
```
