function parseArgs(args) {
  const opts = {}; const positional = [];
  for (let i=0;i<args.length;i++){
    const a = args[i];
    if (!a.startsWith('--')) { positional.push(a); continue; }
    const eq = a.indexOf('=');
    let key = eq>=0 ? a.slice(2,eq) : a.slice(2);
    let val;
    if (eq>=0) val = a.slice(eq+1);
    else if (VALUE_OPTIONS.has(key)) {
      val = args[++i];
      if (val === undefined) throw usageError(`missing value for --${key}`);
    } else if (FLAG_OPTIONS.has(key)) val = true;
    else throw usageError(`unknown option: --${key}`);
    opts[key] = val;
  }
  return {opts, positional};
}
